<?php
namespace App\Http\Controllers;
use App\Services\{CurrencyService as C,WorkspaceContext as W};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class CurrencyController extends Controller {
 public function index(){W::authorize('currencies.view');$currencies=DB::table('tenant_currencies')->where('tenant_id',W::id())->orderByDesc('is_base')->orderBy('code')->get();$history=DB::table('currency_rate_history')->where('tenant_id',W::id())->orderByDesc('effective_at')->limit(30)->get();return view('crm.currencies',compact('currencies','history'));}
 public function store(Request $r){W::authorize('currencies.manage');$d=$r->validate(['code'=>['required','string',Rule::in(array_keys(C::CATALOG))],'rate_to_base'=>'required|numeric|gt:0|lte:1000000000']);$code=$d['code'];abort_unless($code!==W::tenant()->currency,422,'The base currency is already enabled.');$existing=DB::table('tenant_currencies')->where('tenant_id',W::id())->where('code',$code)->exists();abort_if($existing,422,'Currency exists; edit the existing rate.');$catalog=C::CATALOG[$code];DB::transaction(function()use($code,$catalog,$d){DB::table('tenant_currencies')->insert(['tenant_id'=>W::id(),'code'=>$code,'name'=>$catalog[0],'symbol'=>$catalog[1],'precision'=>$catalog[2],'rate_to_base'=>$d['rate_to_base'],'active'=>true,'is_base'=>false,'created_at'=>now(),'updated_at'=>now()]);$this->record($code,$d['rate_to_base']);});return back()->with('success','Currency enabled.');}
 public function update(Request $r,string $code){W::authorize('currencies.manage');$row=$this->find($code);$d=$r->validate(['rate_to_base'=>'required|numeric|gt:0|lte:1000000000','active'=>'required|boolean']);if($row->is_base)abort_unless((float)$d['rate_to_base']===1.0 && $d['active'],422,'Base currency rate is always 1 and cannot be disabled.');DB::transaction(function()use($row,$d,$code){DB::table('tenant_currencies')->where('tenant_id',W::id())->where('code',$code)->update(['rate_to_base'=>$d['rate_to_base'],'active'=>$d['active'],'updated_at'=>now()]);if((string)$row->rate_to_base!==(string)$d['rate_to_base'])$this->record($code,$d['rate_to_base']);});return back()->with('success','Currency and historical rate updated. Existing transaction snapshots remain unchanged.');}
 public function base(Request $r){W::authorize('currencies.manage');$d=$r->validate(['code'=>['required','string',Rule::in(array_keys(C::CATALOG))]]);$target=$this->find($d['code']);abort_unless($target->active,422,'Enable the currency before choosing it as base.');if($target->code===W::tenant()->currency)return back();$tenant=W::id();$used=DB::table('deals')->where('tenant_id',$tenant)->exists()||DB::table('sales_documents')->where('tenant_id',$tenant)->exists()||DB::table('payments')->where('tenant_id',$tenant)->exists();abort_if($used,422,'Base currency cannot change after deals or sales documents exist; historical reporting would require a controlled data migration.');$factor=(float)$target->rate_to_base;abort_unless($factor>0,422);
  DB::transaction(function()use($tenant,$target,$factor){$rows=DB::table('tenant_currencies')->where('tenant_id',$tenant)->lockForUpdate()->get();foreach($rows as $row){$rate=$row->code===$target->code?1:(float)$row->rate_to_base/$factor;DB::table('tenant_currencies')->where('id',$row->id)->update(['rate_to_base'=>number_format($rate,8,'.',''),'is_base'=>$row->code===$target->code,'updated_at'=>now()]);$this->record($row->code,number_format($rate,8,'.',''),$target->code);}DB::table('tenants')->where('id',$tenant)->update(['currency'=>$target->code,'updated_at'=>now()]);});return back()->with('success','Base currency changed before transaction activity.');
 }
 private function record(string $code,$rate,?string $base=null):void{DB::table('currency_rate_history')->insert(['tenant_id'=>W::id(),'code'=>$code,'base_code'=>$base??W::tenant()->currency,'rate_to_base'=>$rate,'source'=>'manual','changed_by'=>auth()->id(),'effective_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}
 private function find(string $code){$row=DB::table('tenant_currencies')->where('tenant_id',W::id())->where('code',$code)->first();abort_unless($row,404);return $row;}
}
